/**
 * Binary node payload (pipeline/build_octree.py):
 *   header: "STM1" | u32 node id | u32 count
 *   record (22 B): f32 x,y,z (pc, ICRS, J2016) | f16 vx,vy,vz (km/s) | f16 absG | u8 colour | u8 flags
 * Decoded into GPU-ready arrays: pos f32x3, vel f32x4 (vx,vy,vz,absG), col u8x4 (colour, flags, 0, 0).
 */
export const RECORD_BYTES = 22;
export const HEADER_BYTES = 12;

export interface DecodedNode {
  id: number;
  count: number;
  pos: Float32Array;
  vel: Float32Array;
  col: Uint8Array;
  /** STM2 (server-filtered): index of each star in the unfiltered node */
  ranks?: Uint16Array;
}

const f16tab = (() => {
  const t = new Float32Array(65536);
  for (let h = 0; h < 65536; h++) {
    const s = h & 0x8000 ? -1 : 1;
    const e = (h >> 10) & 0x1f;
    const m = h & 0x3ff;
    if (e === 0) t[h] = s * m * 2 ** -24;
    else if (e === 31) t[h] = m ? NaN : s * Infinity;
    else t[h] = s * (1 + m / 1024) * 2 ** (e - 15);
  }
  return t;
})();

export function decodeNode(buf: ArrayBuffer): DecodedNode {
  const dv = new DataView(buf);
  const magic = String.fromCharCode(dv.getUint8(0), dv.getUint8(1), dv.getUint8(2), dv.getUint8(3));
  if (magic !== 'STM1' && magic !== 'STM2') throw new Error(`bad node magic ${magic}`);
  const id = dv.getUint32(4, true);
  const count = dv.getUint32(8, true);
  const pos = new Float32Array(count * 3);
  const vel = new Float32Array(count * 4);
  const col = new Uint8Array(count * 4);
  let o = HEADER_BYTES;
  for (let i = 0; i < count; i++, o += RECORD_BYTES) {
    pos[i * 3] = dv.getFloat32(o, true);
    pos[i * 3 + 1] = dv.getFloat32(o + 4, true);
    pos[i * 3 + 2] = dv.getFloat32(o + 8, true);
    vel[i * 4] = f16tab[dv.getUint16(o + 12, true)];
    vel[i * 4 + 1] = f16tab[dv.getUint16(o + 14, true)];
    vel[i * 4 + 2] = f16tab[dv.getUint16(o + 16, true)];
    vel[i * 4 + 3] = f16tab[dv.getUint16(o + 18, true)];
    col[i * 4] = dv.getUint8(o + 20);
    col[i * 4 + 1] = dv.getUint8(o + 21);
  }
  if (magic === 'STM2') {
    const ranks = new Uint16Array(count);
    const off = HEADER_BYTES + count * RECORD_BYTES;
    for (let i = 0; i < count; i++) ranks[i] = dv.getUint16(off + i * 2, true);
    return { id, count, pos, vel, col, ranks };
  }
  return { id, count, pos, vel, col };
}
