/// <reference lib="webworker" />
import { decodeNode } from './nodeFormat';

self.onmessage = async (ev: MessageEvent<{ url: string; key: string }>) => {
  const { url, key } = ev.data;
  try {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const d = decodeNode(await r.arrayBuffer());
    const transfer = [d.pos.buffer, d.vel.buffer, d.col.buffer] as ArrayBuffer[];
    if (d.ranks) transfer.push(d.ranks.buffer as ArrayBuffer);
    (self as unknown as Worker).postMessage({ key, ok: true, node: d }, transfer);
  } catch (e) {
    (self as unknown as Worker).postMessage({ key, ok: false, error: String(e) });
  }
};
